import {seedProfile,createNodes,schedule,status,transition,alerts,expiryState} from './engine.mjs';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fresh=()=>({profile:{...seedProfile},nodes:createNodes(),day:20,events:[{at:'Demo day 10',type:'approval.completed',detail:'Power feasibility approved by simulated connector'},{at:'Demo day 3',type:'workflow.dispatched',detail:'Three independent branches started in parallel'}],messages:[]});
let state;try{state=JSON.parse(localStorage.getItem('flowsync-v1'))||fresh();if(!state.nodes||!state.profile)state=fresh();}catch{state=fresh();}let page='workflow';
const labels={approved:'Approved',in_progress:'In review',blocked:'Blocked',ready:'Ready to start'};
function save(){try{localStorage.setItem('flowsync-v1',JSON.stringify(state));}catch{toast('Browser storage unavailable. Changes last for this session.');}}
function event(type,detail){state.events.unshift({at:`Demo day ${state.day}`,type,detail});save();}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4500);}
const navs=[['workflow','⌘','Approval workflow'],['intake','⊞','Project intake'],['vault','▤','Document vault'],['schemes','◇','Support schemes'],['guidance','✧','Contextual guidance'],['government','▥','Government view'],['architecture','⎔','Technical architecture']];
function render(){page=location.hash.slice(1)||'workflow';if(!navs.some(n=>n[0]===page))page='workflow';$('#nav').innerHTML=navs.map(([id,icon,name])=>`<a href="#${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}><span class="navicon">${icon}</span>${name}${id==='workflow'&&alerts(state).length?`<span class="navcount">${alerts(state).length}</span>`:''}</a>`).join('');$('#crumb').textContent=navs.find(n=>n[0]===page)[2];({workflow, intake, vault, schemes,guidance,government,architecture}[page]||workflow)();}
function head(k,title,sub,actions=''){return `<div class="pagehead"><div><div class="eyebrow">${k}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="actions">${actions}</div></div>`;}
function stat(label,value,foot,accent=false){return `<div class="stat ${accent?'accent':''}"><div class="label">${label}</div><strong>${value}</strong><div class="foot">${foot}</div></div>`;}
function graph(){const sc=schedule(state.nodes),max=Math.max(...Object.values(sc.times).map(t=>t.level)),positions={};for(let l=0;l<=max;l++){const group=state.nodes.filter(n=>sc.times[n.id].level===l);group.forEach((n,i)=>positions[n.id]={x:2+l*24,y:group.length===1?121:12+i*101});}return `<div class="graph-wrap"><div class="graph"><svg aria-hidden="true">${state.nodes.flatMap(n=>n.deps.map(d=>{const a=positions[d],b=positions[n.id];return `<line x1="${a.x+17}%" y1="${a.y+40}" x2="${b.x}%" y2="${b.y+40}" stroke="${sc.critical.includes(d)&&sc.critical.includes(n.id)&&sc.times[d].end===sc.times[n.id].start?'#8fa881':'#c9d6c4'}" stroke-width="1.5" ${state.nodes.find(x=>x.id===d).status==='approved'?'':'stroke-dasharray="4 4"'}/>`;})).join('')}</svg>${state.nodes.map(n=>{const p=positions[n.id],s=status(n,state.nodes);return `<button class="node ${s} ${sc.critical.includes(n.id)?'critical':''}" data-node="${n.id}" style="left:${p.x}%;top:${p.y}px" aria-label="${n.name}, ${labels[s]}"><span class="node-status">${labels[s]}</span><strong>${n.short}</strong><small>${n.dept} · ${n.days} days</small></button>`;}).join('')}</div></div>`;}
function workflow(){const sc=schedule(state.nodes),done=state.nodes.filter(n=>n.status==='approved').length,active=state.nodes.filter(n=>n.status==='in_progress').length,a=alerts(state);$('#main').innerHTML=head('PROJECT OVERVIEW','Your path to operational readiness','A coordinated approval journey. Every dependency, clearly mapped.',`<button class="btn" id="export">↧ Export workflow</button><a class="btn primary" href="#intake">Edit project ↗</a>`)+`<div class="project-strip"><div class="project-left"><div class="project-icon">▥</div><div><div class="project-title">${esc(state.profile.name)}</div><div class="project-meta">${esc(state.profile.sector)} · ${esc(state.profile.district)}, Maharashtra · ₹${esc(state.profile.investment)} Cr investment</div></div></div><span class="badge">FS-DEMO-2026-001</span></div><div class="stats">${stat('Approvals completed',`${done}<small>/ ${state.nodes.length}</small>`,`${active} reviews currently in progress`)}${stat('Dependency-aware estimate',`${sc.total}<small>days</small>`,'Illustrative planned critical path')}${stat('Potential time saved',`${sc.serial-sc.total}<small>days</small>`,`Compared with ${sc.serial} days sequentially`,true)}${stat('Needs attention',`${a.length.toString().padStart(2,'0')}`,a.length?'Illustrative SLA exceeded':'No overdue active reviews')}</div><div class="grid-main"><section class="panel"><div class="panelhead"><div><h2>Approval dependency graph</h2><p>Independent branches run in parallel. Select a node to inspect.</p></div><div class="legend"><span class="done">Approved</span><span class="active">In review</span><span>Blocked</span></div></div>${graph()}<div class="graph-caption"><span>Solid links: prerequisite complete</span><span>DAG · ${state.nodes.length} nodes · ${state.nodes.reduce((s,n)=>s+n.deps.length,0)} dependencies</span></div></section><section class="panel insights"><div class="insight"><div class="insight-title"><span>↗</span> Parallel processing</div><p>Building, ${state.profile.effluent?'environmental and ':''}utility reviews share a completed prerequisite.</p><button class="link" id="explain">View scheduling rationale →</button></div><div class="insight"><div class="insight-title"><span>◷</span> ${a.length?'A review needs attention':'Reviews on track'}</div><p>${a.length?esc(a[0].title)+' is overdue against its demo SLA.':'No active approval has exceeded its demo SLA.'}</p><a href="#government">Inspect department queue →</a></div><div class="insight"><div class="insight-title"><span>▤</span> Keep documents ready</div><p>Check file metadata and expiry dates before the next review.</p><a href="#vault">Open document vault →</a></div></section></div><div class="notice"><strong>Sandbox simulation.</strong> Approval dependencies, processing times and applicability rules are illustrative. Estimates exclude queues and rework. No live NSWS or MAITRI connection.</div><section class="panel"><div class="panelhead"><div><h2>Application activity</h2><p>Simulation clock: day ${state.day}</p></div><button class="btn" id="advance">Advance 5 demo days +</button></div><div class="table-wrap"><table><thead><tr><th>APPROVAL</th><th>DEPARTMENT</th><th>STATUS</th><th>ELAPSED / DEMO SLA</th><th></th></tr></thead><tbody>${state.nodes.map(n=>`<tr><td><strong>${n.name}</strong><small>${n.id.toUpperCase()}-001</small></td><td>${n.dept}</td><td><span class="badge ${status(n,state.nodes)}">${labels[status(n,state.nodes)]}</span></td><td>${n.start!==undefined?Math.max(0,(n.finished??state.day)-n.start)+'d':'—'} / ${n.days}d</td><td><button class="link" data-node="${n.id}">Details ↗</button></td></tr>`).join('')}</tbody></table></div></section>`;bindNodes();$('#advance').onclick=()=>{state.day+=5;event('clock.advanced','Simulation advanced by 5 days');render();};$('#export').onclick=exportWorkflow;$('#explain').onclick=()=>modal('Dependency-aware scheduling',`<p>The engine uses a directed acyclic graph (DAG), topological sorting, and critical path analysis. Each approval starts only after all predecessor approvals complete.</p><div class="details-grid"><div><small>Sequential estimate</small>${sc.serial} days</div><div><small>Parallel estimate</small>${sc.total} days</div></div><p>Critical path: ${sc.critical.map(id=>state.nodes.find(n=>n.id===id).short).join(' → ')}. Estimates use configured demo durations, not measured government performance.</p>`);}
function modal(title,body){$('#detail').innerHTML=`<button class="close" aria-label="Close dialog">×</button><h2>${title}</h2>${body}`;$('#detail').querySelector('.close').onclick=()=>$('#detail').close();$('#detail').showModal();}
function bindNodes(){document.querySelectorAll('[data-node]').forEach(b=>b.onclick=()=>nodeDetail(b.dataset.node));}
function nodeDetail(id){const n=state.nodes.find(n=>n.id===id),s=status(n,state.nodes);modal(n.name,`<span class="badge ${s}">${labels[s]}</span><p>${n.reason}</p><div class="details-grid"><div><small>Responsible department</small>${n.dept}</div><div><small>Illustrative SLA</small>${n.days} days</div></div><h3>Prerequisites</h3><p>${n.deps.length?n.deps.map(d=>{const x=state.nodes.find(n=>n.id===d);return `${x.name} (${labels[status(x,state.nodes)]})`;}).join('<br>'):'No dependencies. This is a root node.'}</p><h3>Document checklist</h3><p>${n.docs.join(', ')||'Internal orchestration milestone. No additional document.'}</p><p class="notice">Demo transitions bypass official document acceptance. They do not submit an application.</p>${s==='ready'?'<button class="btn primary" id="change-status" data-action="start">Start simulated review</button>':s==='in_progress'?'<button class="btn primary" id="change-status" data-action="approve">Simulate department approval</button>':s==='blocked'?'<button class="btn" disabled>Waiting for prerequisite approvals</button>':'<p>Approval recorded in the demo event log.</p>'}`);const b=$('#change-status');if(b)b.onclick=()=>{try{transition(state.nodes,id,b.dataset.action,state.day);event('approval.'+b.dataset.action,n.name);$('#detail').close();render();toast('Workflow updated. Dependencies recalculated.');}catch(e){toast(e.message);}};}
function exportWorkflow(){download('flowsync-workflow.json',JSON.stringify({prototype:true,generatedAt:new Date().toISOString(),profile:state.profile,day:state.day,nodes:state.nodes,scheduling:schedule(state.nodes),events:state.events},null,2),'application/json');}
function download(name,text,type){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
let intake,vault,schemes,guidance,government,architecture;
$('#reset').onclick=()=>modal('Reset workflow demonstration?',`<p>This resets the project, approval statuses and event log. Your local document vault is retained.</p><button class="btn primary" id="confirm-reset">Reset demo workflow</button>` )||setTimeout(()=>{$('#confirm-reset').onclick=()=>{state=fresh();save();$('#detail').close();render();toast('Demonstration reset.');};},0);
window.addEventListener('hashchange',render);

intake=function(){const p=state.profile;$('#main').innerHTML=head('PROJECT CONFIGURATION','A workflow built around your project','Structured intake translates business characteristics into an approval graph.')+`<div class="two-col"><section class="panel"><div class="panelhead"><h2>Applicant & project profile</h2><span class="badge">Rule engine · demo v1</span></div><form id="intake-form" class="formbody"><label class="field">Enterprise name<input name="name" value="${esc(p.name)}" maxlength="100" required></label><div class="form-grid"><label class="field">District<select name="district">${['Pune','Mumbai','Nagpur','Nashik','Aurangabad'].map(v=>`<option ${v===p.district?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">Industry sector<select name="sector">${['Engineering','Food processing','Textiles'].map(v=>`<option ${v===p.sector?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">Proposed investment (₹ crore)<input name="investment" type="number" min="0.01" max="100000" step="0.01" value="${p.investment}" required></label><label class="field">Proposed workforce<input name="workers" type="number" min="1" max="100000" step="1" value="${p.workers}" required></label></div><label class="checkbox"><input type="checkbox" name="effluent" ${p.effluent?'checked':''}>The manufacturing process generates effluent</label><div class="notice"><strong>Regenerating starts a new demo journey.</strong> Approval progress resets. Locally stored documents stay in your vault. The demonstration is limited to Maharashtra.</div><button class="btn primary" type="submit">Generate approval workflow →</button></form></section><div class="stack"><section class="panel formbody"><h2 class="section-title">Explainable applicability</h2><div class="metric-row"><span>Entity, plan, power, fire</span><span class="badge">Base scenario</span></div><div class="metric-row"><span>Process effluent = yes</span><span class="badge">Add CTE</span></div><div class="metric-row"><span>Workforce ≥ 10</span><span class="badge">Add factory review</span></div><p class="muted" style="font-size:13px">These are deliberately simplified demo rules, not verified statutory applicability criteria. Sector and district provide project context; they do not yet select different legal rule sets.</p></section><section class="panel formbody"><div class="eyebrow">TECHNICAL MECHANISM</div><h2>Deterministic rule evaluation</h2><p class="muted" style="font-size:14px">Inputs feed a rule engine, which generates nodes and prerequisite edges. A topological sort validates that the graph is acyclic before scheduling.</p><div class="code">ProjectProfile
  → applicability predicates
  → approval DAG
  → critical path analysis
  → executable state machine</div><p style="font-size:12px" class="muted">Planned AI intake: convert natural language to a validated profile. The prototype uses structured fields for reproducibility.</p></section></div></div>`;$('#intake-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),name=f.get('name').trim();if(!name)return toast('Enter an enterprise name.');state.profile={name,district:f.get('district'),sector:f.get('sector'),investment:Number(f.get('investment')),workers:Number(f.get('workers')),effluent:f.has('effluent')};state.nodes=createNodes(state.profile).map(n=>({...n,status:'pending',start:undefined,finished:undefined}));state.day=0;state.messages=[];event('workflow.generated',`${state.nodes.length} nodes generated from structured intake`);location.hash='workflow';toast('New workflow generated. Start the entity verification node.');};};

let dbPromise;
function vaultDB(){return dbPromise??=new Promise((resolve,reject)=>{const req=indexedDB.open('flowsync-local-vault',1);req.onupgradeneeded=()=>req.result.createObjectStore('documents',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>{dbPromise=null;reject(Error('Local document storage is unavailable in this browser.'));};});}
async function dbOp(mode,operation){const db=await vaultDB();return new Promise((resolve,reject)=>{const tx=db.transaction('documents',mode),req=operation(tx.objectStore('documents'));let value;req.onsuccess=()=>value=req.result;tx.oncomplete=()=>resolve(value);tx.onerror=()=>reject(Error('Could not save the document. Check browser storage space.'));tx.onabort=()=>reject(Error('Document operation was interrupted.'));});}
const allDocs=()=>dbOp('readonly',s=>s.getAll());
let docsCache=[];
vault=async function(){const here=page;$('#main').innerHTML=head('LOCAL DOCUMENT INTELLIGENCE','Documents ready for the next step','Files stay in this browser. Metadata checks help you prepare for review.',`<button class="btn" id="refresh-docs">↻ Refresh expiry checks</button>`)+`<div class="notice"><strong>Device-local vault.</strong> IndexedDB stores file contents on this device. Files are not uploaded. This prototype checks type, size, duplicates and entered expiry dates; it does not perform OCR or verify authenticity. Use sample documents.</div><div class="two-col"><section class="panel"><div class="panelhead"><h2>Add a document</h2><span class="badge">Local storage</span></div><form id="doc-form" class="formbody"><div class="doc-drop"><label class="field">Select a PDF, PNG or JPEG (maximum 10 MB)<input name="file" type="file" accept=".pdf,.png,.jpg,.jpeg" required></label></div><div class="form-grid section-gap"><label class="field">Document category<select name="category">${['Entity certificate','Site plan','Process note','Load schedule','Fire layout','Safety plan','Other'].map(x=>`<option>${x}</option>`).join('')}</select></label><label class="field">Expiry date, if applicable<input name="expiry" type="date"></label></div><button class="btn primary" type="submit" id="save-doc">Validate & save locally</button></form></section><section class="panel formbody"><h2>Pre-validation pipeline</h2><ol class="plainlist"><li>Check file extension and MIME type</li><li>Inspect file header signatures</li><li>Enforce a 10 MB size limit</li><li>Compute a SHA-256 content fingerprint</li><li>Reject duplicate file contents</li><li>Flag expiry within the next 30 days</li></ol><p class="notice">Passing metadata validation does not mean a government department will accept a document. Browser storage is not an encrypted, authenticated production vault.</p></section></div><section class="panel section-gap"><div class="panelhead"><h2>Saved documents</h2><span id="doc-count" class="badge">Loading…</span></div><div id="doc-list" class="table-wrap"><p class="empty">Opening the local vault…</p></div></section>`;$('#refresh-docs').onclick=()=>{vault();toast('Expiry dates recalculated against today’s date.');};$('#doc-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),file=f.get('file'),button=$('#save-doc');button.disabled=true;try{if(!file?.size||file.size>10*1024*1024)throw Error('Choose a non-empty file no larger than 10 MB.');const ext=file.name.split('.').pop().toLowerCase(),allowed={pdf:'application/pdf',png:'image/png',jpg:'image/jpeg',jpeg:'image/jpeg'};if(!allowed[ext]||(file.type&&file.type!==allowed[ext]))throw Error('File extension and MIME type must indicate PDF, PNG or JPEG.');const buffer=await file.arrayBuffer(),bytes=new Uint8Array(buffer);const signature=ext==='pdf'?new TextDecoder().decode(bytes.slice(0,5))==='%PDF-':ext==='png'?[137,80,78,71,13,10,26,10].every((v,i)=>bytes[i]===v):bytes[0]===255&&bytes[1]===216&&bytes[2]===255;if(!signature)throw Error('File signature does not match its extension.');const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',buffer))).map(b=>b.toString(16).padStart(2,'0')).join('');const docs=await allDocs();if(docs.some(d=>d.hash===hash))throw Error('This file already exists in your vault.');await dbOp('readwrite',s=>s.put({id:crypto.randomUUID(),name:file.name,category:f.get('category'),expiry:f.get('expiry'),size:file.size,type:allowed[ext],hash,blob:file,added:new Date().toISOString()}));event('document.metadata_validated',`${f.get('category')} stored locally; no document uploaded`);await vault();toast('Document validated and saved on this device.');}catch(err){toast(err.message);}finally{if(button.isConnected)button.disabled=false;}};try{docsCache=await allDocs();if(page!==here)return;$('#doc-count').textContent=`${docsCache.length} documents`;$('#doc-list').innerHTML=docsCache.length?`<table><thead><tr><th>DOCUMENT</th><th>FINGERPRINT</th><th>EXPIRY</th><th>CHECK RESULT</th><th>ACTIONS</th></tr></thead><tbody>${docsCache.map(d=>{const ex=expiryState(d.expiry);return `<tr><td><strong>${esc(d.name)}</strong><small>${esc(d.category)} · ${Math.ceil(d.size/1024)} KB</small></td><td><small title="${d.hash}">${d.hash.slice(0,12)}…</small></td><td>${esc(d.expiry)||'Not recorded'}</td><td><span class="badge ${ex.tone}">${ex.label}</span></td><td><div class="actions"><button class="link" data-download="${d.id}">Download</button><button class="link" data-delete="${d.id}">Delete</button></div></td></tr>`;}).join('')}</tbody></table>`:'<p class="empty">No documents saved yet. Add a sample document to test validation and expiry monitoring.</p>';document.querySelectorAll('[data-download]').forEach(b=>b.onclick=()=>{const d=docsCache.find(x=>x.id===b.dataset.download);download(d.name,d.blob,d.type);});document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{const d=docsCache.find(x=>x.id===b.dataset.delete);modal('Delete local document?',`<p>Remove ${esc(d.name)} from this browser’s vault?</p><button class="btn primary" id="delete-confirm">Delete document</button>`);$('#delete-confirm').onclick=async()=>{try{await dbOp('readwrite',s=>s.delete(d.id));$('#detail').close();vault();toast('Document removed from local storage.');}catch(e){toast(e.message);}};});}catch(e){if(page===here){$('#doc-count').textContent='Unavailable';$('#doc-list').innerHTML=`<p class="empty">${esc(e.message)}</p>`;}}};

const resources=[{id:'nsws',title:'NSWS approval discovery',kind:'Official discovery portal',source:'https://www.nsws.gov.in/',desc:'Use the Know Your Approvals questionnaire to explore approvals relevant to a proposed business.',tags:['approvals','all'],icon:'◇'},{id:'maitri',title:'Maharashtra single window',kind:'Official portal reference',source:'https://maitri.maharashtra.gov.in/',desc:'The state portal referenced in the project deck. Confirm current procedures and service availability directly with the portal.',tags:['state','all'],icon:'▥'},{id:'demo-capital',title:'Capital support discovery',kind:'Illustrative scheme category',source:'https://www.nsws.gov.in/',desc:'Demo matching rule: investment up to ₹5 crore surfaces a capital-support research category. No specific programme, award or eligibility is asserted.',tags:['finance'],icon:'₹',eligible:()=>state.profile.investment<=5},{id:'demo-food',title:'Sector support discovery',kind:'Illustrative scheme category',source:'https://www.nsws.gov.in/',desc:'Demo matching rule: food processing projects surface a sector-support research category. Verify actual scheme rules and application windows with official sources.',tags:['sector'],icon:'⊞',eligible:()=>state.profile.sector==='Food processing'}];
schemes=function(){let filter='all';$('#main').innerHTML=head('GOVERNMENT SUPPORT','Discover relevant support pathways','Explainable matching with a clear distinction between official sources and demo rules.')+`<div class="notice"><strong>Eligibility remains unverified.</strong> This prototype provides discovery links and illustrative matching categories. It does not calculate benefits or confirm entitlement.</div><div class="tabs" aria-label="Resource filters">${[['all','All resources'],['matched','Matched to project'],['official','Official portals']].map(([id,t])=>`<button class="btn ${id==='all'?'active':''}" data-filter="${id}">${t}</button>`).join('')}</div><div id="scheme-results" class="scheme-grid"></div>`;function draw(){const list=resources.filter(r=>filter==='official'?!r.eligible:filter==='matched'?(!r.eligible||r.eligible()):true);$('#scheme-results').innerHTML=list.map(r=>`<article class="panel scheme"><div class="scheme-icon">${r.icon}</div><div class="eyebrow">${r.kind}</div><h2>${r.title}</h2><p>${r.desc}</p><div class="notice">${r.eligible?(r.eligible()?'Matches the illustrative profile rule.':'Does not match the illustrative profile rule.'):'Relevant to the Maharashtra project context.'}</div><a class="btn" href="${r.source}" target="_blank" rel="noopener noreferrer">Visit official portal ↗</a></article>`).join('');}draw();document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));draw();});};

const knowledge=[{id:'KB-01',keywords:['parallel','simultaneously','workflow','dependencies','critical','time','start','approval','next'],title:'Dependency-aware scheduling',text:()=>{const sc=schedule(state.nodes),ready=state.nodes.filter(n=>status(n,state.nodes)==='ready');return `A node becomes executable only after every prerequisite is approved. Your workflow has ${state.nodes.length} nodes. The planned critical path is ${sc.total} days versus ${sc.serial} days if every task runs sequentially. ${ready.length?'Ready now: '+ready.map(n=>n.name).join(', ')+'.':'No unstarted node is ready yet. Complete the active prerequisite reviews.'} These times and dependency rules are illustrative.`;},source:'Prototype rule catalogue v1',url:null},{id:'KB-02',keywords:['document','documents','upload','expiry','expired','vault','ocr','file'],title:'Local document pre-validation',text:()=>`The local vault validates PDF, PNG and JPEG file headers, checks a 10 MB size limit, and detects duplicates using SHA-256. Expiry alerts use the date you enter and your device clock. File contents stay in IndexedDB. OCR, signature verification and authenticity checks are not implemented.`,source:'Prototype vault specification v1',url:null},{id:'KB-03',keywords:['delay','delayed','overdue','sla','stuck','bottleneck','late'],title:'Service-level monitoring',text:()=>{const a=alerts(state);return a.length?`${a.map(x=>x.title+': '+x.detail).join('. ')}. The Government view shows the active queue and shared applicant metadata. Use a simulated approval to release dependent nodes. No actual department notification is sent.`:'No active review exceeds its illustrative SLA. Advance the demo clock to test a delayed-review scenario.';},source:'Live local workflow state',url:null},{id:'KB-04',keywords:['scheme','schemes','support','grant','subsidy','funding','nsws'],title:'Official approval and support discovery',text:()=>`NSWS provides approval discovery through its Know Your Approvals questionnaire and lists government support schemes. Explore official resources before relying on eligibility guidance. The prototype’s support matching categories are demonstrations; they are not verified schemes or funding promises.`,source:'NSWS official portal · accessed 20 Sep 2026',url:'https://www.nsws.gov.in/'},{id:'KB-05',keywords:['privacy','government','access','official','security','data'],title:'Applicant visibility and data boundaries',text:()=>`The demo Government view displays project metadata and approval statuses, while the document vault stays outside that view. This is a UI separation, not role-based security. Production requires authenticated identities, server-side RBAC/ABAC enforcement, purpose-limited consent and audit logging.`,source:'Prototype architecture and limitations',url:null}];
function answer(q){const tokens=q.toLowerCase().match(/[a-z]+/g)||[],ranked=knowledge.map(k=>({k,score:k.keywords.filter(w=>tokens.includes(w)).length})).sort((a,b)=>b.score-a.score);return ranked[0]?.score?{text:ranked[0].k.text(),source:ranked[0].k.source,id:ranked[0].k.id,url:ranked[0].k.url}:{text:'I could not find a relevant entry in the small prototype knowledge base. Try asking about parallel approvals, delayed reviews, document expiry, support schemes or data access. For a legal requirement, consult the official portal or responsible department.',source:'Abstention: no matching knowledge entry',id:'NO_MATCH'};}
guidance=function(){$('#main').innerHTML=head('CONTEXTUAL GUIDANCE','Understand what comes next','Answers connect your project state with a small, inspectable knowledge base.')+`<div class="two-col"><section class="panel"><div class="panelhead"><h2>Project assistant</h2><span class="badge">Retrieval demo · no LLM</span></div><div class="formbody"><div id="chatlog" class="chatlog" aria-live="polite"></div><div class="tabs"><button class="btn" data-q="Which approvals can run in parallel?">Parallel approvals</button><button class="btn" data-q="Where is my application stuck?">Find delays</button><button class="btn" data-q="How are documents validated?">Document checks</button></div><form id="ask-form"><label class="field">Ask about your project<textarea name="question" rows="2" maxlength="500" placeholder="Which approval should I start next?" required></textarea></label><button class="btn primary">Retrieve an answer →</button></form></div></section><section class="panel formbody"><div class="eyebrow">EVIDENCE BEFORE GENERATION</div><h2>Inspectable retrieval</h2><p class="muted" style="font-size:14px">This prototype uses keyword overlap to retrieve a matching knowledge entry and adds current workflow data to the response. Every answer names its source. Unmatched questions produce an explicit abstention.</p><div class="code">question → tokenization
         → keyword overlap scoring
         → highest-scoring KB entry
         → current workflow context
         → templated answer + source</div><h3 class="section-gap">Production RAG design</h3><p class="muted" style="font-size:14px">A verified regulatory corpus, hybrid retrieval, reranking, and constrained LLM generation would replace the demonstration retriever. Versioned citations and human review remain mandatory.</p><a href="#architecture" class="link">Inspect the technical blueprint →</a></section></div>`;function draw(){const messages=state.messages||[];$('#chatlog').innerHTML=messages.length?messages.map(m=>`<div class="message ${m.role==='user'?'user':''}"><small>${m.role==='user'?'YOU':'FLOWSYNC · RETRIEVED GUIDANCE'}</small>${esc(m.text)}${m.source?`<small style="margin-top:12px">${esc(m.id)} · ${m.url?`<a href="${m.url}" target="_blank" rel="noopener">${esc(m.source)} ↗</a>`:esc(m.source)}</small>`:''}</div>`).join(''):'<div class="message"><small>FLOWSYNC</small>Ask about the approval graph, your current delays, document checks or support discovery. Answers use demo rules and the project state.</div>';$('#chatlog').scrollTop=$('#chatlog').scrollHeight;}function ask(q){q=q.trim();if(!q)return;state.messages??=[];state.messages.push({role:'user',text:q},{role:'assistant',...answer(q)});state.messages=state.messages.slice(-30);save();draw();}draw();$('#ask-form').onsubmit=e=>{e.preventDefault();ask(new FormData(e.target).get('question'));e.target.reset();};document.querySelectorAll('[data-q]').forEach(b=>b.onclick=()=>ask(b.dataset.q));};

government=function(){const departments=[...new Set(state.nodes.map(n=>n.dept))],a=alerts(state),complete=state.nodes.filter(n=>n.status==='approved'),observed=complete.length?Math.round(complete.reduce((s,n)=>s+(n.finished-n.start),0)/complete.length*10)/10:null;$('#main').innerHTML=head('DEPARTMENT OPERATIONS','A shared view of every approval','Inspect queues, identify delays and trace application events.',`<button class="btn" id="audit-export">↧ Export event log</button>`)+`<div class="notice"><strong>Government role preview.</strong> This view uses the same local demo state. There is no authentication or enforced RBAC. Applicant metadata is visible here; local document contents are not displayed.</div><div class="stats">${stat('Departments in workflow',departments.length,'Single synthetic project')}${stat('Active reviews',state.nodes.filter(n=>n.status==='in_progress').length,'Currently being processed')}${stat('Overdue reviews',a.length,'Against illustrative SLAs')}${stat('Mean completed duration',observed===null?'—':`${observed}<small>days</small>`,'Calculated from simulated events',true)}</div><div class="two-col"><section class="panel"><div class="panelhead"><h2>Department workload</h2><span class="badge">Active reviews</span></div><div class="formbody">${departments.map(d=>{const active=state.nodes.filter(n=>n.dept===d&&n.status==='in_progress').length;return `<div class="bar-row"><span>${d}</span><div class="bar"><div style="width:${active?100:0}%"></div></div><b>${active}</b></div>`;}).join('')}<p class="muted" style="font-size:12px">Counts reflect one demo project. No department ranking or real-world performance claim.</p></div></section><section class="panel"><div class="panelhead"><h2>SLA attention queue</h2><span class="badge ${a.length?'warning':''}">${a.length} alerts</span></div>${a.length?a.map(x=>`<div class="alert-card"><h3>${x.title}</h3><p>${x.detail}</p><button class="link" data-node="${x.id}">Inspect application ↗</button></div>`).join(''):'<div class="empty">No overdue active reviews.</div>'}</section></div><section class="panel section-gap"><div class="panelhead"><h2>Applicant profile</h2><span class="badge">Metadata only</span></div><div class="formbody"><h3>${esc(state.profile.name)}</h3><p class="muted" style="font-size:14px">${esc(state.profile.sector)} · ${esc(state.profile.district)} · ₹${esc(state.profile.investment)} Cr · ${esc(state.profile.workers)} proposed workers</p><div class="details-grid"><div><small>Declared process effluent</small>${state.profile.effluent?'Yes':'No'}</div><div><small>Document disclosure</small>Not available in this view</div></div></div></section><section class="panel section-gap"><div class="panelhead"><h2>Application event log</h2><span class="badge">Local, mutable demo log</span></div><div class="table-wrap"><table><thead><tr><th>SIMULATION TIME</th><th>EVENT</th><th>DETAIL</th></tr></thead><tbody>${state.events.map(e=>`<tr><td>${esc(e.at)}</td><td class="audit">${esc(e.type)}</td><td>${esc(e.detail)}</td></tr>`).join('')}</tbody></table></div></section>`;bindNodes();$('#audit-export').onclick=()=>download('flowsync-events.json',JSON.stringify(state.events,null,2),'application/json');};

architecture=function(){$('#main').innerHTML=head('SYSTEM DESIGN & IMPLEMENTATION','Technical architecture','An executable orchestration core, with explicit boundaries for production services.',`<button class="btn" id="technical-export">↧ Export technical brief</button>`)+`<div class="panel"><div class="panelhead"><div><h2>FLOWSYNC orchestration layer</h2><p>Proposed service boundaries sit above existing single-window systems.</p></div><span class="badge">Implementation map</span></div><div class="arch">${[['01 / EXPERIENCE','Applicant workspace','Structured intake, dependency graph, document vault and guidance.','Working in browser'],['02 / ORCHESTRATION','DAG + rule engine','Topological ordering, dependency gating, critical path and SLA checks.','Working in browser'],['03 / LOCAL DATA','IndexedDB + SHA-256','Device-local files, content fingerprints and expiry metadata.','Working in browser'],['04 / KNOWLEDGE','RAG service','Verified sources, hybrid search, pgvector and constrained LLM output.','Planned; keyword retrieval demo'],['05 / INTEGRATION','Department connectors','Authenticated APIs, idempotent status events and reconciliation.','Planned; simulated events'],['06 / GOVERNANCE','Identity + audit','Server-side RBAC/ABAC, consent and append-only audit records.','Planned; role preview only']].map(([id,title,desc,flag])=>`<div class="arch-block"><div class="eyebrow">${id}</div><strong>${title}</strong><p>${desc}</p><span class="badge section-gap">${flag}</span></div>`).join('')}</div></div><div class="two-col section-gap"><section class="panel formbody"><h2 class="section-title">Execution model</h2><div class="code">G = (V, E), directed acyclic graph

ES(v) = max EF(u), for u ∈ predecessors(v)
EF(v) = ES(v) + duration(v)
T_parallel = max EF(v)
T_sequential = Σ duration(v)

executable(v) ⇔ all predecessors approved
critical(v) ⇔ latestStart(v) − ES(v) = 0

pending → ready → in_progress → approved</div><p class="muted" style="font-size:13px">The prototype rejects cycles and missing dependencies. Critical-path estimates assume unlimited parallel capacity, configured durations, no queueing and no rework.</p></section><section class="panel formbody"><h2 class="section-title">Production stack proposed in the deck</h2><div class="metric-row"><span>Experience</span><b>React / Next.js + React Flow</b></div><div class="metric-row"><span>Application API</span><b>FastAPI or NestJS</b></div><div class="metric-row"><span>System of record</span><b>PostgreSQL</b></div><div class="metric-row"><span>Semantic retrieval</span><b>pgvector + LLM</b></div><div class="metric-row"><span>Background jobs</span><b>Redis + Celery / BullMQ</b></div><div class="metric-row"><span>Document extraction</span><b>Tesseract OCR</b></div><p class="muted" style="font-size:12px">These services are a proposed production architecture. This delivered prototype uses native JavaScript modules and browser storage, with no deployed API or model.</p></section></div><section class="panel section-gap"><div class="panelhead"><h2>Vocabulary for your technical presentation</h2></div><div class="table-wrap"><table><thead><tr><th>TERM</th><th>MEANING IN FLOWSYNC</th></tr></thead><tbody>${[['Directed acyclic graph (DAG)','Approvals form a graph with prerequisites and no dependency loops.'],['Topological ordering','Place each prerequisite before approvals that depend on it.'],['Critical path method (CPM)','Find the longest dependency chain that determines the planned completion time.'],['Finite-state machine','Allow only defined approval-state transitions.'],['Idempotency','Process a repeated connector event once without duplicating its effect. Proposed for the API.'],['Retrieval-augmented generation (RAG)','Retrieve verified regulatory passages before generating cited guidance. Proposed for production.'],['RBAC / ABAC','Enforce access based on official roles, department and consent attributes. Proposed for production.'],['Event-driven orchestration','Update dependent work when an approval event arrives. Local simulation implemented.'],['SHA-256 fingerprint','A content digest used to detect duplicate files, not to prove document authenticity.'],['Data minimisation','Disclose only the metadata needed for a permitted purpose. Production enforcement remains to be built.']].map(([t,d])=>`<tr><td><strong>${t}</strong></td><td>${d}</td></tr>`).join('')}</tbody></table></div></section><div class="notice"><strong>Integration boundary.</strong> NSWS and MAITRI are reference platforms, not connected services. Official API access, department partnerships, verified rule ownership and security review are prerequisites for a pilot.</div>`;$('#technical-export').onclick=()=>download('FLOWSYNC-technical-brief.md',technicalBrief(),'text/markdown');};
function technicalBrief(){return `# FLOWSYNC — SIH 2026 Technical Prototype\n\nUnified Industrial Approval & Compliance Orchestrator\nProblem Statement 26130, as supplied in SIH_PPT.pptx.\n\n## Implemented\n- Structured profile intake and deterministic applicability predicates.\n- Directed acyclic graph (DAG), topological ordering and critical path method.\n- Dependency-gated state machine: pending, ready, in_progress, approved.\n- Local simulation clock, illustrative SLA alerts and event log.\n- IndexedDB document vault, file signature checks, SHA-256 deduplication and expiry monitoring.\n- Keyword retrieval with current workflow context, source labels and abstention.\n- Government role preview and derived queue metrics.\n- JSON exports for workflow and event log.\n\n## Proposed production architecture\nReact / Next.js and React Flow frontend; FastAPI or NestJS API; PostgreSQL; pgvector-backed verified regulatory retrieval; Redis and Celery or BullMQ workers; Tesseract OCR; department connector adapters; authenticated RBAC/ABAC with consent-scoped metadata access. Neo4j is optional if cross-project graph queries justify a second datastore.\n\n## Planning algorithm\nES(v) = max EF(predecessors(v)); EF(v) = ES(v) + duration(v). Parallel makespan is max EF(v). Sequential baseline is the sum of durations. Critical nodes have zero slack. No queue, capacity or rework model is included.\n\n## Demonstration\n1. Inspect the seeded graph and its calculated critical path.\n2. Complete an active review; observe prerequisite gating and newly ready nodes.\n3. Advance the clock by five days; inspect SLA attention in Government view.\n4. Add a sample PDF, re-add it to test duplicate rejection, and enter a near expiry date.\n5. Ask which approvals can run in parallel; inspect the retrieved source.\n6. Change the intake to no effluent and fewer than 10 workers; inspect the regenerated graph.\n\n## Boundaries\nAll approval rules, durations and sample project data are illustrative. No live government integration, official submissions, OCR, LLM, encrypted vault, production RBAC, multi-user database or delivered SMS/email exists in this build. Document presence does not gate simulated approvals. Portal links are references, not eligibility determinations. Local event history is mutable and is not a compliance-grade audit trail.\n\n## Reference platforms\n- NSWS: https://www.nsws.gov.in/ — portal reviewed 20 September 2026.\n- MAITRI: https://maitri.maharashtra.gov.in/ — supplied deck reference; automated access unavailable during this build.\n`;}

if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});for(const tool of [{name:'read_approval_workflow',title:'Read approval workflow',description:'Read the local demo approval statuses, illustrative scheduling estimates and SLA alerts. No files are returned.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(input&&Object.keys(input).length)throw Error('No parameters accepted');return {day:state.day,nodes:state.nodes.map(n=>({id:n.id,name:n.name,status:status(n,state.nodes)})),schedule:schedule(state.nodes),alerts:alerts(state)};}},{name:'advance_simulation_clock',title:'Advance demo clock',description:'Advance the local demonstration by five days and refresh the displayed SLA alerts. Sends no external notifications.',inputSchema:{type:'object',properties:{days:{type:'integer',enum:[5]}},required:['days'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||input.days!==5||Object.keys(input).length!==1)throw Error('days must equal 5');state.day+=5;event('clock.advanced','Simulation advanced by 5 days');render();return {day:state.day,overdue:alerts(state).length};}}]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}}
render();
